const raw = $input.first().json;
const body = raw.body || raw;
const actionId = body.action_id || 'act_unknown';
const actionType = (body.action_type || 'PURCHASE_ORDER').toUpperCase();
const businessId = body.business_id || 'biz_001';
const payload = body.payload || {};
const config = body.config || {};

const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const randHex = Math.random().toString(16).substring(2, 6).toUpperCase();
const orderNumber = payload.order_number || `PO-${dateStr}-${randHex}`;

const items = Array.isArray(payload.items) ? payload.items : [];
const itemsSummary = items.length > 0
  ? items.map(i => `${i.quantity} units of ${i.name} (Rs ${i.subtotal || (i.quantity * i.unit_cost)})`).join(', ')
  : '25L Farm Fresh A2 Milk, 20 packs Organic Eggs, 10 Artisanal Sourdough Loaves, and 15 tubs Greek Yogurt';

const supplierName = payload.supplier_name || 'MilkyWay Fresh Foods Co.';
const supplierPhone = config.supplier_phone || payload.supplier_phone || '+918496074290';
const totalAmount = payload.total_amount || 4500;

const calleTaskPrompt = `Call ${supplierPhone} (${supplierName}). You are OperatorOS calling on behalf of Rajesh Kumar, owner of Green Valley Organic Grocers in Indiranagar, Bengaluru. Place purchase order ${orderNumber} for tomorrow 6:00 AM delivery: ${itemsSummary}, totaling ${totalAmount} rupees. Ask the supplier to confirm stock availability and 6 AM delivery slot.`;

const customers = Array.isArray(payload.customers) ? payload.customers : [
  { name: 'Priya Sharma', phone: '+919880112233', outstanding_due: 1850, due_since_days: 9 },
  { name: 'Vikram Rao', phone: '+919880445566', outstanding_due: 2400, due_since_days: 14 }
];

let telegramText = '';
if (actionType === 'PAYMENT_REMINDER') {
  const lines = customers.map(c => `• *${c.name}*: ₹${c.outstanding_due} (overdue ${c.due_since_days || 7} days) — UPI: greenvalley@okaxis`).join('\n');
  telegramText = `💳 *Green Valley Organic Grocers — Courteous Payment Reminder*\n\nNamaste! Gentle reminder from Rajesh Kumar at Green Valley Organic Grocers regarding store credit balances:\n\n${lines}\n\n*Total Pending:* ₹${payload.total_due || 4250}\nThank you for shopping with us!`;
} else if (actionType === 'CAMPAIGN_BROADCAST') {
  telegramText = `🚀 *${payload.campaign_name || 'Weekend Organic Harvest Special'}*\n\n${payload.copy_text || 'Enjoy 15% OFF on Wildflower Honey, A2 Milk & Sourdough this weekend!'}\n\n📊 *Channel:* ${payload.channel || 'WhatsApp & Telegram Broadcast'}\n👥 *Audience:* ${payload.target_audience || '142 Loyal Customers'}\n💰 *Projected Revenue:* ₹${payload.estimated_revenue || 22397.5}`;
} else {
  telegramText = `📦 *Purchase Order & CALL-E Supplier Call Dispatched*\n\n*Order No:* ${orderNumber}\n*Supplier:* ${supplierName} (${supplierPhone})\n*Items:* ${itemsSummary}\n*Total Value:* ₹${totalAmount}\n*Delivery:* Tomorrow 06:00 AM\n*CALL-E Voice Agent:* Outbound supplier order call initiated.`;
}

return [{
  json: {
    action_id: actionId,
    action_type: actionType,
    business_id: businessId,
    order_number: orderNumber,
    supplier_name: supplierName,
    supplier_phone: supplierPhone,
    items_summary: itemsSummary,
    total_amount: totalAmount,
    calle_task_prompt: calleTaskPrompt,
    telegram_text: telegramText,
    customers: customers,
    payload: payload,
    config: {
      calle_api_key: config.calle_api_key || '',
      telegram_bot_token: config.telegram_bot_token || '',
      telegram_chat_id: config.telegram_chat_id || '',
      google_sheet_id: config.google_sheet_id || '1a5RFLAso_9ESi8F71TanbElvodlR-QrvYdGyE4j14go',
      spreadsheet_webhook_url: config.spreadsheet_webhook_url || ''
    },
    timestamp: now.toISOString(),
    execution_id: `n8n-cloud-${randHex}`
  }
}];

const ctx = $('Prepare Action Context').item.json;
return [{
  json: {
    Timestamp: ctx.timestamp,
    Order_No: ctx.order_number,
    Action_Branch: 'PURCHASE_ORDER',
    Supplier_Name: ctx.supplier_name,
    Supplier_Phone: ctx.supplier_phone,
    Ordered_Items: ctx.items_summary,
    Total_Amount_INR: ctx.total_amount,
    Delivery_Slot: 'Tomorrow 06:00 AM',
    Status: 'PO_DISPATCHED_AND_CALLE_CALLED'
  }
}];

